\section{Introduction}

The phrase ``the whole is greater than the sum of its parts'' is usually a metaphor. Information theory can turn it into an inequality. Take components $X_1,\dots,X_k$ and a target label $L$, and compare what the whole tuple says about $L$ with what the parts say individually:
\[
\Syn(X_1,\dots,X_k;L)=I\big((X_1,\dots,X_k);L\big)-\sum_{i=1}^kI(X_i;L).
\]
When the components carry redundant information about $L$, the synergy can be negative. When they carry complementary information, it is positive. The extreme case, which we call \emph{pure emergence}, is when every $I(X_i;L)$ vanishes and the left-hand term does not.

This paper was motivated by an empirical observation made in a series of experiments on composite moduli. At the semiprime level, three irreducible components each appeared to carry approximately zero information about a ``composite type'' label, while the composite label itself was read at $1.8170$ bits. We call the effect \emph{the whole exceeds the sum}. Our aims are:
\begin{enumerate}[label=(\arabic*)]
\item to state and prove exact theorems explaining why ``approximately zero'' is in fact \emph{exactly} zero under uniform sampling;
\item to compute the information carried by the whole exactly, and to show that it is the maximum possible (\emph{saturation});
\item to instantiate the theory on the most natural arithmetic composite label, the Jacobi symbol;
\item to determine which labels are compatible with the measured figure of $1.8170$ bits.
\end{enumerate}
The results fall into three layers. The abstract layer (Section~\ref{sec:abstract}) gives the fibre-swap criterion and the determined-label law for arbitrary finite probability spaces. The group layer (Sections~\ref{sec:sum}--\ref{sec:capacity}) treats sum labels in finite abelian groups, proves a sharp emergence dichotomy, and proves the capacity bound together with saturation. The arithmetic layer (Section~\ref{sec:jacobi}) applies all of this to the Jacobi symbol, and also proves the four-types theorem for the measured read.

\section{Mutual information of observables and two exact criteria}\label{sec:abstract}

\subsection{Setting}
Let $\Omega$ be a finite sample space carrying weights $\mu:\Omega\to\R_{\ge0}$ with $\sum_\omega\mu(\omega)=1$. An \emph{observable} is a map $X:\Omega\to\alpha$ into a finite set $\alpha$.

\begin{definition}[Joint law]
For observables $X:\Omega\to\alpha$ and $Y:\Omega\to\beta$, the \emph{joint table} is
\[
p_{X,Y}(a,b)=\sum_{\omega:\,X(\omega)=a,\ Y(\omega)=b}\mu(\omega).
\]
Its marginals are $p_X(a)=\sum_bp_{X,Y}(a,b)$ and $p_Y(b)=\sum_ap_{X,Y}(a,b)$. The entries are nonnegative and add up to $\sum_\omega\mu(\omega)=1$.
\end{definition}

\begin{definition}[Mutual information]
For a nonnegative table $p$ on $\alpha\times\beta$ with marginals $p_X,p_Y$,
\[
I(p)=\sum_{a\in\alpha}\sum_{b\in\beta}p(a,b)\log\frac{p(a,b)}{p_X(a)\,p_Y(b)},
\]
with natural logarithms and the convention that terms with $p(a,b)=0$ vanish. For observables we write $I(X;Y)=I(p_{X,Y})$. This is measured in \emph{nats}. The value in \emph{bits} is $I/\log2$.
\end{definition}

\begin{definition}[Label entropy]
$H(Y)=-\sum_bp_Y(b)\log p_Y(b)$.
\end{definition}

\subsection{Tables constant in the label}
\begin{lemma}[Constant tables carry nothing]\label{lem:const}
Let $p$ be a nonnegative table on $\alpha\times\beta$ with total mass $1$, and suppose $p(a,b)=p(a,b')$ for all $a,b,b'$. Then $I(p)=0$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $p(a,b)=c_a$. Then $p_X(a)=|\beta|c_a$ and $p_Y(b)=\sum_ac_a=1/|\beta|$, because the total mass is $|\beta|\sum_ac_a=1$. Whenever $c_a>0$ the ratio inside the logarithm equals $1$, and $\log1=0$. The terms with $c_a=0$ vanish by convention.
\end{proof}

\subsection{The fibre-swap criterion}
For a label $Y:\Omega\to\beta$ and $b\in\beta$, the \emph{fibre} over $b$ is $Y^{-1}(b)$.

\begin{theorem}[Fibre-swap criterion]\label{thm:swap}
Let $X:\Omega\to\alpha$ and $Y:\Omega\to\beta$ be observables. Suppose that for every pair $b,b'\in\beta$ there is a bijection $\tau:\Omega\to\Omega$ such that
\begin{enumerate}[label=(\roman*)]
\item $\mu(\tau\omega)=\mu(\omega)$ for all $\omega$ ($\tau$ preserves the weights);
\item $X(\tau\omega)=X(\omega)$ for all $\omega$ ($\tau$ fixes the observable);
\item $Y(\tau\omega)=b'$ if and only if $Y(\omega)=b$ ($\tau$ carries the fibre over $b$ onto the fibre over $b'$).
\end{enumerate}
Then $I(X;Y)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Fix $a\in\alpha$. Reindex the sum defining $p_{X,Y}(a,b')$ along $\tau$. Properties (i)--(iii) turn the summand at $\tau\omega$ into the summand of $p_{X,Y}(a,b)$ at $\omega$, so $p_{X,Y}(a,b')=p_{X,Y}(a,b)$. The joint table is therefore constant in the label coordinate, and Lemma~\ref{lem:const} gives $I=0$.
\end{proof}

\begin{remark}
The criterion is a \emph{symmetry certificate}. Exhibiting the swaps proves that $X$ and $Y$ are exactly independent, so no estimate is needed.
\end{remark}

\subsection{The determined-label law}
\begin{lemma}[Swaps make the label uniform]\label{lem:uniform}
If for all $b,b'$ there is a weight-preserving bijection $\tau$ of $\Omega$ carrying the fibre over $b$ onto the fibre over $b'$, then $\Pr[Y=b]=1/|\beta|$ for every $b$.
\end{lemma}
\begin{proof}[Proof sketch]
Reindexing along $\tau$ shows that all the fibre masses are equal. They add up to $1$.
\end{proof}

\begin{theorem}[Determined-label law]\label{thm:det}
Let $X:\Omega\to\alpha$ and $Y:\Omega\to\beta$, and suppose $Y=\varphi\circ X$ for some $\varphi:\alpha\to\beta$. Suppose also that the label fibres can be swapped by weight-preserving bijections as in Lemma~\ref{lem:uniform}. Then $I(X;Y)=\log|\beta|$.
\end{theorem}
\begin{proof}[Proof sketch]
Since $Y$ is a function of $X$, we have $p_{X,Y}(a,b)=p_X(a)$ if $\varphi(a)=b$ and $0$ otherwise. By Lemma~\ref{lem:uniform}, $p_Y(b)=1/|\beta|$. Each nonzero term is $p_X(a)\log\frac{p_X(a)}{p_X(a)/|\beta|}=p_X(a)\log|\beta|$. Summing over $a$ gives $\log|\beta|$.
\end{proof}

\section{Sum labels in finite abelian groups}\label{sec:sum}

\subsection{The model}
Let $A$ be a finite abelian group, written additively, and let $k\in\N$. The sample space is $\Omega=A^k$ with the uniform weights $\mu(\omega)=|A|^{-k}$.

\begin{definition}
The \emph{components} are the coordinate observables $x_i(\omega)=\omega_i$. For $S\subseteq\{1,\dots,k\}$, the \emph{sub-family observable} is $\omega\mapsto(\omega_i)_{i\in S}$. The \emph{composite label} is the sum $L(\omega)=\sum_{i=1}^k\omega_i\in A$.
\end{definition}

The key identity is that translating a single coordinate translates the label: $L(\omega+c\,e_j)=L(\omega)+c$, where $c\,e_j$ is the vector with $c$ in coordinate $j$ and $0$ elsewhere. So the translation $\tau_{j,c}:\omega\mapsto\omega+c\,e_j$ with $c=b'-b$ carries the fibre over $b$ onto the fibre over $b'$. It preserves the uniform weights, and it fixes every coordinate other than $j$.

\subsection{Blindness of proper sub-families and the value of the whole}
\begin{theorem}[Every proper sub-family is blind]\label{thm:proper}
For every proper subset $S\subsetneq\{1,\dots,k\}$, $I\big((x_i)_{i\in S};L\big)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Choose $j\notin S$. The translations $\tau_{j,b'-b}$ fix the restriction to $S$, preserve the weights and swap the label fibres. Theorem~\ref{thm:swap} applies.
\end{proof}

\begin{theorem}[The whole carries everything]\label{thm:whole}
For $k\ge1$, $I\big((x_1,\dots,x_k);L\big)=\log|A|$.
\end{theorem}
\begin{proof}[Proof sketch]
$L$ is a function of the full tuple, and the translations $\tau_{1,b'-b}$ supply fibre swaps. Theorem~\ref{thm:det} applies with $\beta=A$.
\end{proof}

\begin{corollary}[Single components are blind]\label{cor:single}
If $k\ge2$, then $I(x_i;L)=0$ for every $i$.
\end{corollary}

\subsection{The synergy theorem and the emergence dichotomy}
\begin{theorem}[The Whole Exceeds the Sum]\label{thm:synergy}
Let $k\ge2$ and $|A|>1$. Then
\[
I\big((x_1,\dots,x_k);L\big)-\sum_{i=1}^kI(x_i;L)=\log|A|,
\]
and in particular $\sum_iI(x_i;L)=0<\log|A|=I\big((x_1,\dots,x_k);L\big)$.
\end{theorem}
\begin{proof}[Proof sketch]
Combine Theorem~\ref{thm:whole} and Corollary~\ref{cor:single}, and note that $\log|A|>0$ when $|A|>1$.
\end{proof}

\begin{proposition}[No emergence with one component]\label{prop:k1}
For $k=1$, $I(x_1;L)=\log|A|$.
\end{proposition}
\begin{proof}[Proof sketch]
Here $L=x_1$. Apply Theorem~\ref{thm:det} with $\varphi=\id$.
\end{proof}

\begin{theorem}[Emergence dichotomy]\label{thm:dich}
Let $|A|>1$, $k\ge1$ and $1\le i\le k$. Then $I(x_i;L)=0$ if and only if $k\ge2$.
\end{theorem}
\begin{proof}[Proof sketch]
The reverse direction is Corollary~\ref{cor:single}. For the forward direction, if $k=1$ then Proposition~\ref{prop:k1} gives $I(x_1;L)=\log|A|>0$.
\end{proof}

At least two irreducible parts are therefore needed before the whole can know something that no part knows.

\section{Capacity and saturation}\label{sec:capacity}

\subsection{Gibbs' inequality}
\begin{theorem}[Gibbs' inequality, uniform form]\label{thm:gibbs}
If $q:\beta\to\R_{\ge0}$ satisfies $\sum_bq_b=1$, then $-\sum_{b\in\beta}q_b\log q_b\le\log|\beta|$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $n=|\beta|$. This is positive because $\sum_b q_b=1$ forces $\beta\ne\varnothing$. For every $b$ we claim $-q_b\log q_b-q_b\log n\le\frac1n-q_b$. If $q_b=0$ this reads $0\le1/n$. If $q_b>0$, the left side is $q_b\log\frac1{nq_b}$, and the inequality $\log t\le t-1$ at $t=1/(nq_b)$ bounds it by $q_b\big(\frac1{nq_b}-1\big)=\frac1n-q_b$. Summing over $b$ gives $H(q)-\log n\le1-1=0$.
\end{proof}

\subsection{The label-capacity bound}
\begin{lemma}[Term-wise comparison]\label{lem:term}
For a nonnegative table $p$ and all $(a,b)$,
\[
p(a,b)\log\frac{p(a,b)}{p_X(a)p_Y(b)}\le-p(a,b)\log p_Y(b).
\]
\end{lemma}
\begin{proof}[Proof sketch]
If $p(a,b)=0$ both sides vanish. Otherwise $0<p(a,b)\le p_X(a)$ and $p(a,b)\le p_Y(b)$, so $\log\frac{p(a,b)}{p_X(a)p_Y(b)}=\log\frac{p(a,b)}{p_X(a)}-\log p_Y(b)\le-\log p_Y(b)$.
\end{proof}

\begin{theorem}[Information is bounded by label entropy]\label{thm:IH}
For every nonnegative table, $I(p)\le H(Y)$.
\end{theorem}
\begin{proof}[Proof sketch]
Sum Lemma~\ref{lem:term} over $(a,b)$ and exchange the order of summation. Summing over $a$ turns the right-hand side into $-p_Y(b)\log p_Y(b)$.
\end{proof}

\begin{theorem}[Label-capacity bound]\label{thm:cap}
For every nonnegative table on $\alpha\times\beta$ of total mass $1$, $I(p)\le\log|\beta|$. Consequently, for observables $X,Y$ on a finite probability space, $I(X;Y)\le\log|\beta|$.
\end{theorem}
\begin{proof}[Proof sketch]
Combine Theorem~\ref{thm:IH} with Theorem~\ref{thm:gibbs} applied to $q=p_Y$, which is nonnegative and sums to $1$.
\end{proof}

\subsection{Saturated emergence}
\begin{theorem}[Synergy is saturated]\label{thm:sat}
In the sum-label model with $k\ge2$:
\begin{enumerate}[label=(\arabic*)]
\item every component is blind: $I(x_i;L)=0$ for all $i$;
\item the whole carries $I\big((x_1,\dots,x_k);L\big)=\log|A|$;
\item every observable $X:A^k\to\alpha$, for any finite $\alpha$, satisfies $I(X;L)\le I\big((x_1,\dots,x_k);L\big)$.
\end{enumerate}
\end{theorem}
\begin{proof}[Proof sketch]
Items (1) and (2) are Corollary~\ref{cor:single} and Theorem~\ref{thm:whole}. Item (3) follows from Theorem~\ref{thm:cap} with $\beta=A$, together with item (2).
\end{proof}

The emergent information is therefore extremal in two senses. The parts carry the minimum possible amount (zero), and the whole carries the maximum that any observable could carry.

\subsection{How many label types does a read require?}
\begin{lemma}\label{lem:log3}
$\log3<1.8170\cdot\log2$; that is, $\log_23<1.8170$.
\end{lemma}
\begin{proof}[Proof sketch]
$3^5=243<256=2^8$, so $5\log3<8\log2$, which gives $\log_23<8/5=1.6<1.8170$.
\end{proof}

\begin{theorem}[Four-types theorem]\label{thm:four}
Let $X,Y$ be observables on a finite probability space. If $I(X;Y)/\log2\ge1.8170$, then $|\beta|\ge4$.
\end{theorem}
\begin{proof}[Proof sketch]
The sample space is nonempty because its weights add up to $1$, so $\beta$ is nonempty. If $|\beta|\le3$, then Theorem~\ref{thm:cap} gives $I(X;Y)\le\log|\beta|\le\log3<1.8170\log2$, a contradiction.
\end{proof}

