\section{The arithmetic instance: the Jacobi symbol}\label{sec:jacobi}

\subsection{Legendre bits}
Let $p$ be an odd prime. For a unit $a\in(\Z/p\Z)^\times$, define the \emph{Legendre bit} $\beta_p(a)=0$ if $a$ is a square in $\Z/p\Z$ and $\beta_p(a)=1$ otherwise. Thus $\leg ap=(-1)^{\beta_p(a)}$.

\begin{lemma}[Nonresidues flip the bit]\label{lem:flip}
If $p$ is an odd prime and $u$ is a quadratic nonresidue unit mod $p$, then $\beta_p(ua)=\beta_p(a)+1$ in $\Z/2\Z$ for every unit $a$.
\end{lemma}
\begin{proof}[Proof sketch]
The quadratic character $\chi$ of $\Z/p\Z$ is multiplicative, takes the value $-1$ exactly on nonsquares, and takes the value $+1$ on nonzero squares, because the characteristic is not $2$. Hence $\chi(ua)=-\chi(a)$.
\end{proof}

\begin{lemma}\label{lem:nonres}
Every odd prime has a quadratic nonresidue unit.
\end{lemma}

\subsection{The residue model and the Jacobi label}
Let $P_1,\dots,P_k$ be odd primes, and let $\mathcal R=\prod_{i=1}^k(\Z/P_i\Z)^\times$ with the uniform law. When the $P_i$ are distinct and $N=P_1\cdots P_k$, the Chinese remainder theorem identifies $\mathcal R$ with $(\Z/N\Z)^\times$. A uniformly random unit mod $N$ is then a vector of independent, uniform prime residues.

\begin{definition}[Jacobi label]
For $\omega\in\mathcal R$, $J(\omega)=\sum_{i=1}^k\beta_{P_i}(\omega_i)\in\Z/2\Z$. The \emph{prime components} are the coordinates $\omega\mapsto\omega_i$, and the \emph{residues on $S$} are $\omega\mapsto(\omega_i)_{i\in S}$.
\end{definition}

\begin{theorem}[Bridge to the Jacobi symbol]\label{thm:bridge}
Let $P_1,\dots,P_k$ be primes and let $a\in\Z$ be prime to each $P_i$. Then $\leg{a}{P_1\cdots P_k}=\prod_i\leg a{P_i}$, and
\[
\leg{a}{P_1\cdots P_k}=1\iff\sum_{i=1}^k\beta_{P_i}(a)=0\ \text{in }\Z/2\Z.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The first identity follows by induction on $k$ from multiplicativity of the Jacobi symbol in its lower argument. Each Legendre symbol equals $(-1)^{\beta_{P_i}(a)}$, and a product of signs $(-1)^{g_i}$ equals $(-1)^{\sum g_i}$.
\end{proof}

\subsection{Label swaps by nonresidue multiplication}
\begin{lemma}\label{lem:flipcoord}
Fix $j$ and a nonresidue $u$ mod $P_j$, and let $u\,e_j\in\mathcal R$ have $u$ in coordinate $j$ and $1$ elsewhere. Then $J\big((u\,e_j)\omega\big)=J(\omega)+1$.
\end{lemma}

\begin{lemma}[Label-swap family]\label{lem:swapfam}
For each $j$ and $b,b'\in\Z/2\Z$ there is a bijection $\tau$ of $\mathcal R$ that preserves the uniform law, fixes every coordinate $i\ne j$, and satisfies $J(\tau\omega)=b'\iff J(\omega)=b$.
\end{lemma}
\begin{proof}[Proof sketch]
If $b=b'$, take $\tau=\id$. Otherwise take multiplication by $u\,e_j$ with $u$ a nonresidue (Lemma~\ref{lem:nonres}), and use Lemma~\ref{lem:flipcoord}.
\end{proof}

\subsection{Emergence of the Jacobi symbol}
\begin{theorem}[Proper statistics are blind]\label{thm:jproper}
Let $S\subsetneq\{1,\dots,k\}$, and let $X:\mathcal R\to\alpha$ be any observable that depends only on the coordinates in $S$. Then $I(X;J)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Choose $j\notin S$. The swaps of Lemma~\ref{lem:swapfam} fix $X$. Theorem~\ref{thm:swap} applies.
\end{proof}

\begin{corollary}
The complete residue vector on any proper subset of the primes is blind to $J$. In particular, knowing $a$ modulo every prime but one reveals nothing about the Jacobi symbol.
\end{corollary}

\begin{theorem}[The whole carries one bit]\label{thm:onebit}
For $k\ge1$, $I(\id;J)=\log2$, that is, exactly one bit. The vector of Legendre bits alone also carries exactly one bit about $J$.
\end{theorem}
\begin{proof}[Proof sketch]
$J$ is a function of $\omega$ and of the Legendre-bit vector. Lemma~\ref{lem:swapfam} supplies fibre swaps, and Theorem~\ref{thm:det} with $|\beta|=2$ applies.
\end{proof}

\begin{theorem}[The Whole Exceeds the Sum, arithmetic form]
For $k\ge2$ odd primes, $\sum_iI(\omega_i;J)=0$ and $I(\id;J)=\log2$, so $\sum_iI(\omega_i;J)<I(\id;J)$.
\end{theorem}

\begin{corollary}[Semiprimes]
For odd primes $p,q$, the residues of $a$ mod $p$ and mod $q$ each carry $0$ bits about the Jacobi label of a uniformly random unit $a$ mod $pq$, while together they carry exactly $1$ bit.
\end{corollary}

\begin{corollary}[Three primes]
For odd primes $P_1,P_2,P_3$, every pair of prime components carries $0$ bits about $J$, while the triple carries exactly $1$ bit.
\end{corollary}

\begin{theorem}[Jacobi-label capacity]\label{thm:jcap}
For $k\ge2$ odd primes: every observable $X$ of a uniformly random unit satisfies $I(X;J)\le1$ bit, the full residue vector carries exactly $1$ bit, and every single prime component carries exactly $0$ bits.
\end{theorem}
\begin{proof}[Proof sketch]
The first claim is Theorem~\ref{thm:cap} with $|\beta|=2$. The other two are Theorems~\ref{thm:onebit} and~\ref{thm:jproper}.
\end{proof}

\subsection{Worked enumerations}
\begin{example}[$N=15$]
The units are $\{1,2,4,7,8,11,13,14\}$. Tabulated against $J$, each class mod $3$ contains exactly $2$ units of each label, and each class mod $5$ contains exactly $1$ unit of each label. Both tables are flat. Four units have symbol $+1$ and four have symbol $-1$, so the full residue carries one bit.
\end{example}

\begin{example}[$N=105$]
Among the $48$ units, every class mod $15$ (the pair of residues mod $3$ and mod $5$) contains as many units with $J=0$ as with $J=1$. Each label occurs $24$ times.
\end{example}

\section{Algorithms}
\begin{description}[style=nextline]
\item[Exact mutual information of observables.] Accumulate the joint table in one pass over $\Omega$, in time $O(|\Omega|)$. Then compute the marginals and evaluate the defining sum in time $O(|\mathrm{supp}\,p|)$.
\item[Fibre-swap certificate.] Check properties (i)--(iii) of Theorem~\ref{thm:swap} for the swaps from one base label value, in time $O(|\beta||\Omega|)$. Success proves $I(X;Y)=0$ exactly and, by Lemma~\ref{lem:uniform}, that the label is uniform.
\item[Minimal alphabet for a read.] A read of $r$ bits needs at least $\lceil2^r\rceil$ label types. For $r=1.8170$ the answer is $4$, certified by $3^5<2^8$.
\item[Jacobi label by Legendre bits.] Compute each $\beta_{P_i}(a)$ by Euler's criterion $a^{(P_i-1)/2}\bmod P_i$ and add the bits mod $2$. By Theorem~\ref{thm:bridge} this agrees with the reciprocity algorithm.
\end{description}

\section{Discussion}
\subsection{What the theory says about the measured effect}
Under the uniform law, ``approximately zero bits per component'' is \emph{exactly} zero (Theorems~\ref{thm:proper} and~\ref{thm:jproper}), so nonzero estimates are sampling artefacts. The figure $1.8170$ bits cannot be the Jacobi bit, since no observable carries more than one bit about $J$ (Theorem~\ref{thm:jcap}), and it requires at least four label types (Theorem~\ref{thm:four}). If there are exactly four types, the capacity is $2$ bits and the read lies below capacity. For example, a symmetric four-symbol channel with error rate about $2.1\%$ yields $1.817$ bits. If the label is a sum label in a group of order at least $4$, Theorems~\ref{thm:proper}--\ref{thm:synergy} give exact per-component blindness and a whole worth at least $2$ bits.

\subsection{Boundaries}
For $k=1$ there is no emergence (Theorem~\ref{thm:dich}). For the prime $2$ the unit group is trivial and has no nonresidue, so the swap of Lemma~\ref{lem:swapfam} does not exist. This is why all primes are assumed odd.

\subsection{Connections}
Additive secret sharing over $A$ is precisely the sum-label model. Theorem~\ref{thm:proper} says that any $k-1$ shares are perfectly hiding, and Theorem~\ref{thm:sat} adds that the reconstruction is information-theoretically optimal. For $A=\Z/2\Z$ the model is the XOR gate, the standard example of pure synergy. Theorem~\ref{thm:jproper} is an exact, unconditional statement that partial residue knowledge says nothing about the Jacobi symbol.

\section{Future directions}
\begin{enumerate}[label=(\arabic*)]
\item \textbf{Fourier-support characterisation.} For a uniform law on $G=\prod_iG_i$ and a label $L$, we conjecture that a sub-family $S$ is blind if and only if no non-trivial character of $G$ supported on $S$ correlates with the level sets of $L$. The fibre-swap criterion would be the translation-invariant special case.
\item \textbf{Synergy--entropy identity for character labels.} For a character label $\chi:G\to\mu_m$ that is non-trivial on every coordinate, we conjecture that the synergy equals $\log|\mathrm{im}\,\chi|$. The Jacobi label is the case $m=2$.
\item \textbf{Identifying the four-type label} at the semiprime level, and computing its exact emergent information.
\item \textbf{Non-uniform laws.} Give quantitative leakage bounds for approximate fibre swaps.
\end{enumerate}

\section{Conclusion}
A symmetry certificate (the fibre swap) shows that the parts carry exactly nothing. A determination argument shows that the whole carries the full label entropy. Gibbs' inequality shows that nothing can carry more. For sums in finite abelian groups the synergy is exactly $\log|A|$, with a sharp threshold at two components. For the Jacobi symbol modulo a product of at least two odd primes, every proper statistic carries $0$ bits and the whole carries the maximal $1$ bit. A measured read of $1.8170$ bits can only come from a label with at least four types.

