from fractions import Fraction
from math import ceil, log2
from typing import Tuple


def minimal_label_types(read_bits: float) -> int:
    """Smallest alphabet size n with log2 n >= read_bits (capacity bound)."""
    n = max(1, ceil(2 ** read_bits - 1e-12))
    while log2(n) < read_bits:
        n += 1
    return n


def integer_certificate(read: Fraction, n: int) -> Tuple[int, int, int, int]:
    """Find integers (p, q) with n^q < 2^p and p/q <= read, certifying log2 n < read
    by exact integer arithmetic. Returns (n, q, p, q) meaning n^q < 2^p."""
    for q in range(1, 200):
        p = (read.numerator * q) // read.denominator
        if Fraction(p, q) <= read and n ** q < 2 ** p:
            return (n, q, p, q)
    raise ValueError("no certificate found")


if __name__ == "__main__":
    r = Fraction(18170, 10000)
    n = minimal_label_types(float(r))
    print("minimal number of label types for 1.8170 bits:", n)
    base, e1, p, _ = integer_certificate(r, n - 1)
    print(f"certificate: {base}^{e1} = {base**e1} < 2^{p} = {2**p}  =>  log2 {base} < {p}/{e1} <= 1.8170")

from math import gcd, log2, prod
from collections import Counter
from itertools import combinations
from typing import Dict, List, Tuple


def legendre_bit(a: int, p: int) -> int:
    """Euler's criterion: 0 if a is a quadratic residue mod the odd prime p, else 1."""
    return 0 if pow(a, (p - 1) // 2, p) == 1 else 1


def jacobi_label(a: int, primes: List[int]) -> int:
    """Additive Jacobi label: sum of Legendre bits mod 2; (a|N) = (-1)^label."""
    return sum(legendre_bit(a, p) for p in primes) % 2


def emergence_profile(primes: List[int]) -> Dict[Tuple[int, ...], float]:
    """Bits carried about the Jacobi label by residues modulo every subset of the primes."""
    N = prod(primes)
    units = [a for a in range(N) if gcd(a, N) == 1]
    n = len(units)
    out: Dict[Tuple[int, ...], float] = {}
    for size in range(len(primes) + 1):
        for S in combinations(primes, size):
            joint = Counter((tuple(a % p for p in S), jacobi_label(a, primes)) for a in units)
            px = Counter(); py = Counter()
            for (x, y), c in joint.items():
                px[x] += c; py[y] += c
            I = sum(c / n * log2((c / n) / ((px[x] / n) * (py[y] / n))) for (x, y), c in joint.items())
            out[S] = 0.0 if abs(I) < 1e-12 else I
    return out


if __name__ == "__main__":
    for S, bits in emergence_profile([3, 5, 7]).items():
        print(f"residues mod {S!s:<10}: {bits:.6f} bits")
